function createCounter() {
  let count = 0;              // captured by closure
  return {
    increment: () => ++count,
    value: () => count,
  };
}
const counter = createCounter();
counter.increment();
counter.increment();
console.log(counter.value()); // 2 — count lives on

// Classic loop pitfall:
for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log('var:', i)); // 3, 3, 3
}
for (let j = 0; j < 3; j++) {
  setTimeout(() => console.log('let:', j)); // 0, 1, 2
}

const timer = {
  seconds: 0,
  start() {
    // arrow keeps `this` = timer from start()
    setInterval(() => {
      this.seconds++;
      console.log(this.seconds);
    }, 1000);
  },
};
timer.start();

// Regular method form would lose `this` inside setInterval:
// setInterval(function () { this.seconds++; }, 1000); // NaN error

function greet(greeting, punct) {
  return `${greeting}, ${this.name}${punct}`;
}

const user = { name: 'Ada' };
greet.call(user, 'Hello', '!');     // 'Hello, Ada!'
greet.apply(user, ['Hi', '?']);     // 'Hi, Ada?'
const bound = greet.bind(user, 'Hey');
bound('.');                          // 'Hey, Ada.'

const numbers = [1, 2, 3, 4];

numbers.map(n => n * n)       // takes a function
       .filter(n => n % 2 === 0)
       .reduce((sum, n) => sum + n, 0); // 20

// Returning a function:
const multiplyBy = factor => n => n * factor;
const double = multiplyBy(2);
double(21); // 42
